using System;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Threading;using UnityEngine;using W=EarthUnscripted.NewbridgePrototype.NewbridgeWorld;
namespace EarthUnscripted.Editor {
 public static class BuildingPipelineVerification {
 const BindingFlags H=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;
 public static void Run(){int checks=0;void Need(bool ok,string why){checks++;if(!ok)throw new Exception("BUILDING PIPELINE "+why);}var root=new GameObject("Ordered numeric building pipeline fixture");
 try{var w=root.AddComponent<W>();var houses=new List<W.Building>();for(int i=0;i<19;i++){float x=20+i*10;houses.Add(new W.Building{id="building-"+i,kind="house",height=5+i%4,roofHeight=2,roofShape=i%2==0?"gabled":"flat",underground=i==3,centre=new Vector3(x+3,10,23),points=new[]{new Vector3(x,10,20),new Vector3(x+6,10,20),new Vector3(x+6,10,26),new Vector3(x,10,26),new Vector3(x,10,20)}});}houses[7].points=new[]{Vector3.zero,Vector3.one};
 var map=new W.Map{minX=0,minZ=0,maxX=400,maxZ=400,coreMinX=0,coreMinZ=0,coreMaxX=400,coreMaxZ=400,nx=5,nz=5,gridStep=100,heights=Enumerable.Repeat(10f,25).ToArray(),features=Array.Empty<W.Feature>(),buildings=houses.ToArray(),waterAreas=Array.Empty<W.WaterArea>(),routes=Array.Empty<W.DriveRoute>()};
 typeof(W).GetField("workingMap",H).SetValue(w,map);typeof(W).GetMethod("IndexMap",H).Invoke(w,new object[]{map});var batch=typeof(W).GetNestedType("Batch",H);object B()=>Activator.CreateInstance(batch,H,null,new object[]{"fixture",null,false},null);var a=B();var b=B();var c=B();var d=B();
 void Drain(IEnumerator job){var stack=new Stack<IEnumerator>();stack.Push(job);var clock=System.Diagnostics.Stopwatch.StartNew();while(stack.Count>0){if(clock.Elapsed.TotalSeconds>15)throw new Exception("Building fixture timeout");if(!stack.Peek().MoveNext()){(stack.Pop() as IDisposable)?.Dispose();continue;}if(stack.Peek().Current is IEnumerator inner)stack.Push(inner);else Thread.Sleep(1);}}
 foreach(var house in houses)Drain((IEnumerator)typeof(W).GetMethod("PrepareBuilding",H).Invoke(w,new[]{house,a,b}));
 Drain((IEnumerator)typeof(W).GetMethod("PrepareBuildingRange",H).Invoke(w,new object[]{houses,c,d,map,null}));
 foreach(var pair in new[]{new[]{a,c},new[]{b,d}}){var vertices=(IEnumerable<Vector3>)batch.GetProperty("Vertices",H).GetValue(pair[0]);var other=(IEnumerable<Vector3>)batch.GetProperty("Vertices",H).GetValue(pair[1]);Need(vertices.SequenceEqual(other),"exact ordered vertices match serial compilation");Need(((IEnumerable<int>)batch.GetProperty("Indices",H).GetValue(pair[0])).SequenceEqual((IEnumerable<int>)batch.GetProperty("Indices",H).GetValue(pair[1])),"exact ordered triangle indices match serial compilation");Need(vertices.Any(),"real building geometry compiled");}
 Need(w.CompletedBuildingJobs==34,"valid real building jobs consumed exactly once per path; invalid/underground skipped");Need(ReferenceEquals(typeof(W).GetField("workingMap",H).GetValue(w),map),"capture restores shared map ownership");var empty=B();Drain((IEnumerator)typeof(W).GetMethod("PrepareBuildingRange",H).Invoke(w,new object[]{houses,empty,B(),map,new Func<bool>(()=>false)}));Need((int)batch.GetProperty("VertexCount",H).GetValue(empty)==0,"retired source cancels before publication");
 }finally{UnityEngine.Object.DestroyImmediate(root);}Debug.Log("BUILDING PIPELINE PASS "+checks);}
 }
}
